public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordToKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    // If start equals end, travel is trivially possible
    boolean same = true;
    for (int i = 0; i < n; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) return "can be travelled";

    // Build adjacency list
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 2 * n) continue; // skip malformed entries
        int[] from = new int[n];
        int[] to = new int[n];
        System.arraycopy(path, 0, from, 0, n);
        System.arraycopy(path, n, to, 0, n);
        String fromKey = coordToKey.apply(from);
        String toKey = coordToKey.apply(to);
        graph.computeIfAbsent(fromKey, k -> new java.util.ArrayList<>()).add(toKey);
        graph.computeIfAbsent(toKey, k -> new java.util.ArrayList<>()).add(fromKey);
    }

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // BFS to find if a path exists
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

