public static String convertDatesToWeekdays(String date) {
    java.time.format.DateTimeFormatter inputFormatter = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy", java.util.Locale.US);
    java.time.LocalDate localDate = java.time.LocalDate.parse(date, inputFormatter);
    String monthName = localDate.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.US);
    int day = localDate.getDayOfMonth();
    int year = localDate.getYear();
    String weekday = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.US);
    return String.format("%s %d, %d is a %s", monthName, day, year, weekday);
}

